#include <iostream>

namespace N {
    template<typename T>
    class Y {
    public:
        void mf() { std::cout << "Y<" << typeid(T).name() << ">::mf()" << std::endl; }
    };
}

// Explicit instantiation of class template Y with int in global namespace
template class Y<int>;

// Explicit instantiation of member function mf() of Y<double> in namespace N
template void N::Y<double>::mf();

int main() {
    N::Y<int> y1;
    y1.mf(); // Calls instantiated template for int
    N::Y<double> y2;
    y2.mf(); // Calls explicitly instantiated mf() for double
    return 0;
}
